export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = 9.8;
  const t = time;
  const height = launchSpeed * t - 0.5 * gravity * t * t;
  const velocity = launchSpeed - gravity * t;

  const maxH = (launchSpeed * launchSpeed) / (2 * gravity);
  const maxT = launchSpeed / gravity;
  const clampedH = Math.max(0, height);

  const lane = sdk.panel({ x: 40, y: 40, w: 560, h: 320, title: "Vertical Toss", state: t < maxT ? "Moving up" : (t === maxT ? "Still for an instant" : "Moving down"), id: "lane.toss" });

  const axisY = sdk.axis("axis.y", { x: 80, y: 320, length: 240, orientation: "y", min: 0, max: 2.5, label: "Height", unit: "m", ticks: [0, 0.5, 1.0, 1.5, 2.0, 2.5] });

  const ballY = 320 - (clampedH / 2.5) * 240;
  const ball = sdk.circle("ball.toss", 200, ballY, 24, { role: "output" });

  const ground = sdk.groundMark("ground.mark", 200, 320, 60, "Launch");

  let motionStateStr = "Moving up";
  if (Math.abs(velocity) < 0.05) {
    motionStateStr = "Still for an instant";
  } else if (velocity < 0) {
    motionStateStr = "Moving down";
  }

  const vecV = sdk.vector("vec.v", { x: 230, y: ballY }, { value: velocity, direction: "up" }, { scale: 15, minLength: 12, label: "v" });
  const vecA = sdk.vector("vec.a", { x: 170, y: ballY }, { value: -gravity, direction: "up" }, { scale: 5, minLength: 12, label: "a" });

  const callout = sdk.callout(260, ballY - 20, [motionStateStr, "Gravity pulls down"]);

  const objects = [lane, axisY, ground, ball, ...vecV, ...vecA, callout];

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "motionState", value: motionStateStr },
        { id: "gravityState", value: "Pulling down" }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime: maxT,
      apexHeight: maxH,
      velocity,
      height
    }
  };
}
